<script setup lang="ts">
import{onBeforeUnmount,onMounted,ref}from'vue';import{api,type ApiResponse}from'@whaashop/shared';
interface Rec{id:number;productId:number;productName:string;productImage?:string;subtitle?:string;price:number}interface Sale{id:number;productId:number;productName:string;productImage?:string;skuSpec:string;originalPrice:number;price:number;stock:number;endAt:string}
const featured=ref<Rec[]>([]),newest=ref<Rec[]>([]),sales=ref<Sale[]>([]),now=ref(Date.now());let timer:number|undefined;onMounted(async()=>{timer=window.setInterval(()=>now.value=Date.now(),1000);const[f,n,s]=await Promise.all([api.get<ApiResponse<Rec[]>>('/shop/promotions/recommendations',{params:{position:'HOME_FEATURED'}}),api.get<ApiResponse<Rec[]>>('/shop/promotions/recommendations',{params:{position:'HOME_NEW'}}),api.get<ApiResponse<Sale[]>>('/shop/promotions/flash-sales')]);featured.value=f.data.data;newest.value=n.data.data;sales.value=s.data.data});onBeforeUnmount(()=>clearInterval(timer));function countdown(end:string){const remaining=Math.max(0,new Date(end).getTime()-now.value);if(!remaining)return{ended:true,days:'00',hours:'00',minutes:'00',seconds:'00'};const total=Math.floor(remaining/1000),pad=(value:number)=>String(value).padStart(2,'0');return{ended:false,days:pad(Math.floor(total/86400)),hours:pad(Math.floor(total%86400/3600)),minutes:pad(Math.floor(total%3600/60)),seconds:pad(total%60)}}
</script>
<template><div v-if="sales.length||featured.length||newest.length" class="promotion-showcase container"><section v-if="sales.length" class="flash-section"><div class="promotion-heading"><div><span>LIMITED OFFERS</span><h2>限时秒杀</h2></div><p>限量好价，先到先得</p></div><div class="promotion-grid"><router-link v-for="item in sales" :key="item.id" :to="`/products/${item.productId}`" class="promotion-product flash"><div><img :src="item.productImage"><em>秒杀</em></div><h3>{{item.productName}}</h3><div v-if="!countdown(item.endAt).ended" class="sale-countdown"><span v-if="countdown(item.endAt).days!=='00'"><b>{{countdown(item.endAt).days}}</b><i>天</i></span><span><b>{{countdown(item.endAt).hours}}</b><i>时</i></span><em>:</em><span><b>{{countdown(item.endAt).minutes}}</b><i>分</i></span><em>:</em><span><b>{{countdown(item.endAt).seconds}}</b><i>秒</i></span></div><div v-else class="sale-ended">活动已结束</div><small>活动库存仅剩 {{item.stock}} 件</small><p><b>¥{{item.price}}</b><del>¥{{item.originalPrice}}</del></p></router-link></div></section><section v-if="featured.length||newest.length" class="recommend-section"><div class="promotion-heading"><div><span>CURATED FOR YOU</span><h2>运营精选推荐</h2></div><p>来自商城后台的实时推荐</p></div><div class="promotion-grid"><router-link v-for="item in [...featured,...newest]" :key="`${item.id}-${item.productId}`" :to="`/products/${item.productId}`" class="promotion-product"><div><img :src="item.productImage"><em>推荐</em></div><h3>{{item.productName}}</h3><small>{{item.subtitle}}</small><p><b>¥{{item.price}}</b></p></router-link></div></section></div></template>
<style scoped>.promotion-showcase{padding:20px 0 70px}.promotion-showcase section{margin-top:45px}.flash-section{padding:28px;border-radius:24px;background:linear-gradient(130deg,#7c2d12,#c2410c);color:#fff}.promotion-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:20px}.promotion-heading span{font-size:10px;letter-spacing:2px;color:#fb923c;font-weight:900}.flash-section .promotion-heading span{color:#fdba74}.promotion-heading h2{font-size:29px;margin:5px 0 0}.promotion-heading p{color:#a88772}.flash-section .promotion-heading p{color:#ffedd5}.promotion-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.promotion-product{display:block;padding:10px 10px 16px;border:1px solid #f2e1d5;border-radius:16px;background:#fff;color:#52382a;text-decoration:none}.promotion-product>div{position:relative;overflow:hidden;border-radius:11px}.promotion-product img{width:100%;aspect-ratio:1.35;display:block;object-fit:cover}.promotion-product em{position:absolute;left:8px;top:8px;padding:4px 8px;border-radius:99px;background:#f97316;color:#fff;font-size:9px;font-style:normal}.promotion-product h3{margin:11px 3px 5px;font-size:14px}.promotion-product small{display:block;height:30px;margin:0 3px;color:#a88772;font-size:10px}.promotion-product p{margin:8px 3px 0}.promotion-product p b{font-size:19px;color:#ea580c}.promotion-product del{margin-left:7px;color:#b9a79b;font-size:11px}.flash-section .promotion-product.flash{border-color:#ffffff22}@media(max-width:850px){.promotion-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.promotion-showcase{width:94vw}.flash-section{padding:18px}.promotion-heading{align-items:flex-start;flex-direction:column}.promotion-heading p{margin-bottom:0}.promotion-grid{grid-template-columns:1fr 1fr;gap:9px}}
.sale-countdown{display:flex!important;align-items:end;gap:3px!important;margin:7px 3px 6px;padding:7px 8px;border-radius:9px!important;background:#fff2e6}.sale-countdown span{display:flex;align-items:end;gap:2px}.sale-countdown b{min-width:21px;padding:3px;border-radius:5px;background:#ea580c;color:#fff;text-align:center;font-size:12px}.sale-countdown i{color:#9a3412;font-size:8px;font-style:normal}.sale-countdown>em{position:static!important;padding:0!important;background:none!important;color:#ea580c!important;font-size:13px!important;font-weight:900}.sale-ended{margin:7px 3px 6px;padding:8px;border-radius:8px!important;background:#f1f5f9;color:#64748b;text-align:center;font-size:11px}.flash .sale-countdown+small,.flash .sale-ended+small{height:auto;margin-bottom:3px}@media(max-width:520px){.sale-countdown{gap:1px!important;padding:6px 4px}.sale-countdown b{min-width:18px;font-size:10px}.sale-countdown i{display:none}}
.promotion-grid{grid-template-columns:repeat(4,minmax(0,1fr));align-items:start}.promotion-product{min-width:0;height:auto;align-self:start;overflow:hidden}.promotion-product>div:first-child{height:0;padding-bottom:74%;overflow:hidden;border-radius:11px;background:linear-gradient(135deg,#fff2e6,#ffedd5)}.promotion-product>div:first-child img{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto;display:block;object-fit:cover}.promotion-product h3{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.flash-section{overflow:hidden}@media(max-width:850px){.promotion-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
